from pathlib import Path
from html import escape
D=Path('webb/assets')
def svg(name,art,title):
    text=f'''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 600 300" role="img"><title>{escape(title)}</title><defs><marker id="arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M0 0L10 5L0 10Z" fill="#9b432c"/></marker></defs><rect width="600" height="300" rx="18" fill="#f4f6ef"/><g stroke="#365e4d" stroke-width="3.5" stroke-linecap="round" stroke-linejoin="round">{art}</g></svg>'''
    (D/f'{name}.svg').write_text(text)
def line(x1,y1,x2,y2,color='#365e4d'):
    return f'<path d="M{x1} {y1}L{x2} {y2}" stroke="{color}" fill="none"/>'
def label(x,y,text):return f'<text x="{x}" y="{y}" text-anchor="middle" stroke="none" fill="#365e4d" font-family="system-ui,sans-serif" font-size="17">{text}</text>'
def person(x,y,color='#a9bb9e',scale=1):
    return f'<g transform="translate({x} {y}) scale({scale})"><circle cy="-53" r="18" fill="#e4c6a8"/><path d="M-21 -28Q0 -37 21 -28L28 24H-28Z" fill="{color}"/><path d="M-14 24L-18 66M14 24L18 66" fill="none"/><path d="M-23 -21L-37 10M23 -21L37 10" fill="none"/></g>'
svg('preposition-in','''<path d="M190 90Q300 37 410 90L425 241H175Z" fill="#bbcba9"/><ellipse cx="300" cy="92" rx="110" ry="38" fill="#fff"/><path d="M247 63Q246 24 300 24Q354 24 353 63" fill="none"/><g transform="translate(260 90) rotate(-13)" stroke="#9b432c" fill="#dbaa79"><circle r="17"/><circle r="7" fill="#fff"/><path d="M17 0H72V12H58V4H47V12H35V4H17Z"/></g><path d="M186 111Q299 152 414 111" fill="none"/>''','Nycklar ligger inuti en öppen väska.')
svg('preposition-on','''<path d="M126 159H474V183H126Z" fill="#d8c3a3"/><path d="M153 183V265M448 183V265" fill="none"/><path d="M243 127H371V158H243Z" fill="#fff"/><path d="M243 116H371V128H243Z" fill="#9daf99"/><path d="M243 155H371"/><path d="M252 135H362M252 145H362" stroke="#c0c6b9"/>''','En bok ligger ovanpå ett skrivbord.')
svg('preposition-under','''<path d="M145 115H455V164H145Z" fill="#d9e0d0"/><path d="M145 70V229M455 111V229"/><path d="M169 94H236Q251 100 246 118H169Z" fill="#fff"/><path d="M145 133H455"/><g fill="#bc8664" stroke="#9b432c"><path d="M233 196L257 187L285 208Q304 216 303 227H221Q214 214 233 196Z"/><path d="M320 194L344 186L373 207Q391 214 391 226H308Q302 211 320 194Z"/></g>''','Ett par skor står under en säng.')
svg('preposition-between',person(175,160,'#a9bb9e')+person(300,160,'#d7ad91')+person(425,160,'#9aaac0')+label(175,270,'Leo')+label(300,270,'Maya')+label(425,270,'Sam'),'Maya står mellan Leo och Sam.')
svg('preposition-next','''<rect x="273" y="93" width="232" height="154" rx="5" fill="#d8dfcb"/><path d="M256 93L389 39L521 93Z" fill="#c0cdae"/><rect x="360" y="169" width="55" height="78" rx="3" fill="#fff"/><g fill="#fff"><rect x="298" y="116" width="40" height="35"/><rect x="440" y="116" width="40" height="35"/></g><path d="M166 125V249"/><rect x="125" y="71" width="82" height="61" rx="9" fill="#fff"/><g fill="#adc0a4"><rect x="141" y="83" width="49" height="33" rx="5"/><circle cx="151" cy="120" r="4"/><circle cx="181" cy="120" r="4"/></g>'''+label(389,143,'School'),'En busshållplats står bredvid skolan.')
svg('preposition-wall','''<rect x="104" y="38" width="392" height="229" rx="5" fill="#e8e6db"/><rect x="209" y="72" width="184" height="140" rx="4" fill="#fff"/><circle cx="260" cy="120" r="21" fill="#c7d5ba"/><path d="M285 109H367M285 129H348M235 168H369M235 185H333" stroke="#93a486"/><circle cx="217" cy="80" r="3" fill="#9b432c"/><circle cx="385" cy="80" r="3" fill="#9b432c"/>''','En affisch sitter på en vägg.')
svg('preposition-into','''<path d="M330 45H477V263H330Z" fill="#dfe6d4"/><path d="M348 69H455V263H348Z" fill="#fff"/><path d="M347 263L282 248V71L347 69Z" fill="#d0bc9d"/><circle cx="298" cy="162" r="4" fill="#9b432c"/>'''+person(157,151,'#a9bb9e',.8)+'''<path d="M194 193Q262 179 360 179" stroke="#9b432c" stroke-width="6" fill="none" marker-end="url(#arrow)"/>''','En person går från korridoren in genom dörren till ett rum.')
svg('preposition-across','''<path d="M0 186Q147 154 300 186T600 186V267H0Z" fill="#d8e4e6" stroke="none"/><path d="M96 169H504V202H96Z" fill="#d4c09b"/><path d="M111 170V128M489 170V128M111 129H489"/><path d="M151 131V169M200 131V169M250 131V169M300 131V169M350 131V169M400 131V169M451 131V169"/>'''+person(93,126,'#a9bb9e',.6)+'''<path d="M162 113H475" stroke="#9b432c" stroke-width="6" fill="none" marker-end="url(#arrow)"/>''','En person går över en bro från ena sidan till den andra.')
svg('preposition-through','''<path d="M176 233V117Q176 53 222 53H382Q428 53 428 117V233Z" fill="#bacba9"/><ellipse cx="179" cy="163" rx="26" ry="72" fill="#506753"/><ellipse cx="426" cy="163" rx="26" ry="72" fill="#506753"/><path d="M61 239H542M61 253H542" stroke="#aab5a2"/><g transform="translate(61 208)"><rect x="0" y="-45" width="78" height="64" rx="9" fill="#d8b497"/><rect x="10" y="-35" width="25" height="24" rx="3" fill="#fff"/><rect x="45" y="-35" width="23" height="24" rx="3" fill="#fff"/><circle cx="18" cy="23" r="9" fill="#506753"/><circle cx="60" cy="23" r="9" fill="#506753"/></g><path d="M114 150H525" stroke="#9b432c" stroke-width="6" fill="none" marker-end="url(#arrow)"/>''','Ett tåg färdas genom en tunnel från öppningen till utgången.')
# A simple room provides a consistent source for there is/are and noun descriptions.
svg('study-room','''<path d="M70 38H530V256H70Z" fill="#f0eee4"/><rect x="107" y="59" width="93" height="78" fill="#deeaec"/><path d="M153 59V137M107 98H200"/><rect x="362" y="71" width="123" height="122" rx="4" fill="#cfbd9d"/><path d="M363 113H485M363 154H485"/><g fill="#a0b397"><rect x="372" y="79" width="14" height="32"/><rect x="391" y="80" width="14" height="31"/><rect x="417" y="119" width="13" height="33"/><rect x="438" y="119" width="13" height="33"/></g><path d="M122 182H333V198H122Z" fill="#c6d1ba"/><path d="M139 198V256M316 198V256"/><path d="M203 153H263V183H203Z" fill="#a6b8cb"/><path d="M216 145V141Q236 117 254 141V145" fill="none"/><circle cx="178" cy="168" r="13" fill="#cb8e66"/><path d="M383 230V193M417 230V193M378 193H423V175H378Z" fill="#c6d1ba"/>''','Ett rum med ett fönster, ett bord, en stol, böcker, en väska och en boll.')
